/usr/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from copy import deepcopy
from solution import page

rows = [
    {'score': 0, 'id': 'c', 'team': 'blue'},
    {'score': 3, 'id': 'b', 'team': 'blue', 'extra': {'value': []}},
    {'score': 3, 'id': 'a', 'team': 'blue'},
    {'score': 3, 'id': 'aa', 'team': 'red'},
    {'score': -1, 'id': 'd', 'team': 'blue'},
]
original = deepcopy(rows)
assert page(rows, 1, [3, 'aa'], 'blue') == {'rows': [rows[1]], 'next': [3, 'b']}
assert page(rows, 2, [3, 'ab'], 'blue') == {'rows': [rows[1], rows[0]], 'next': [0, 'c']}
assert page(rows, 2, [3, 'b'], 'blue') == {'rows': [rows[0], rows[4]], 'next': None}
assert page(rows, 50, None, None) == {'rows': [rows[i] for i in (2, 3, 1, 0, 4)], 'next': None}
assert page(rows, 1, [-1, 'd'], None) == {'rows': [], 'next': None}
assert page(rows, 1, None, '') == {'rows': [], 'next': None}
assert rows == original
for invalid in (0, 51, True, 1.0):
    try:
        page(rows, invalid, None, None)
    except ValueError:
        pass
    else:
        raise AssertionError(invalid)
print('Pagination edge cases passed')
PY"

